"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["29800"],{28356(e){e.exports=JSON.parse('{"id":"FIN-1315","slug":"central-counterparty","term":"Central Counterparty (CCP)","also_known_as":["CCP"],"difficulty":"Advanced","definition":"A central counterparty (CCP) is a clearing house that steps in between the two sides of a trade, becoming the buyer to every seller and the seller to every buyer, and guaranteeing that trades will be completed even if one party defaults.","explanation":["Without a central counterparty, each trader is exposed to the risk that the party on the other side fails to pay or deliver. A CCP replaces many bilateral exposures with a single exposure to the CCP, a process called novation.","CCPs manage risk in several ways. They require members to post initial margin when they open positions and variation margin as prices change. They maintain default funds, contributed by members, and their own capital to absorb losses. If a member defaults, the CCP uses these resources, in a set order called the default waterfall, to cover losses.","For example, if a trader holding a large futures position goes bankrupt, the CCP closes or transfers the position, using the trader\'s margin to cover any loss, so that other traders are not affected.","After the 2008 financial crisis, regulators required many standardised over-the-counter derivatives to be cleared through CCPs. This has reduced counterparty risk, but concentrated it in a small number of CCPs, which are now regulated as critical financial infrastructure."],"note":"","total":1500,"prev":{"slug":"central-bank-independence","term":"Central Bank Independence"},"next":{"slug":"central-limit-theorem","term":"Central Limit Theorem"}}')}}]);